`timescale 1ns/10ps
`default_nettype wire
// Self-check testbench: drives your ce_frac with a fixed random stimulus and compares every output against
// known-correct values recorded from the reference implementation (X bits of the reference are not checked).
// Do not edit this file or tb_selfcheck_vectors.vh.  Prints PASS, or FAIL lines for the first mismatches.
module tb_selfcheck;
    integer seed, seed0, errs, checks, known, cyc, cycles;
    reg  clk = 0;
    reg  reset = 0;
    wire dut_ce;
    ce_frac #(.W(8), .NUM(5), .DEN(12)) dut (.clk(clk), .reset(reset), .ce(dut_ce));
    function [31:0] r32(input integer dummy); begin r32 = $random(seed); end endfunction
    function [63:0] r64(input integer dummy); begin r64 = {$random(seed), $random(seed)}; end endfunction
    // chance(n): true with probability n/256
    function chance(input integer n); reg [7:0] v; begin v = $random(seed); chance = (v < n); end endfunction

    initial begin #(0); forever #(5) clk = ~clk; end
    always @(posedge clk) cyc <= cyc + 1;
    always @(negedge clk) begin
        if (chance(1)) reset <= 1'b1; else reset <= 1'b0;
    end
    reg [0:0] sc_cur;
    integer sc_ptr, sc_sptr, kn_t, sc_k, sc_first; reg bad_t;
    integer sc_nerr [0:0]; integer sc_fcyc [0:0];   // per signal: mismatching sample points, first cycle
    reg [0:0] sc_badv;
`include "tb_selfcheck_vectors.vh"
    task automatic cmp_bits_(input [1023:0] g, input [1023:0] c, input integer w, output reg bad, output integer kn);
        integer i;
        begin bad = 0; kn = 0;
            if (g === c) begin if (^g[1023:0] !== 1'bx) kn = w; end
            else for (i = 0; i < w; i = i + 1) if (g[i] === 1'b0 || g[i] === 1'b1) begin
                kn = kn + 1; if (c[i] !== g[i]) bad = 1; end
        end
    endtask
    task show_first; integer sh; begin
        $display("FAIL: first mismatch at cycle %0d (sample point %0d); every value below is from that sample point", cyc, checks);
        $display("FAIL:   inputs reset=%h", reset);
        sh = 0;
        if (sc_badv[0]) begin if (sh < 6) $display("FAIL:   output ce expected %h got %h (wrong bits %h)", sc_cur[0:0], dut_ce, sc_cur[0:0] ^ dut_ce); sh = sh + 1; end
        if (sh > 6) $display("FAIL:   (%0d more signals differ at this sample point)", sh - 6);
        sh = 0; $write("FAIL:   outputs that match here:");
        if (!sc_badv[0]) begin if (sh < 10) $write(" ce=%h", dut_ce); sh = sh + 1; end
        if (sh > 10) $write(" (+%0d more)", sh - 10);
        $display("");
    end endtask
    task check; begin
        while (sc_ptr + 1 < SC_NEV && sc_ev_k[sc_ptr + 1] <= checks) sc_ptr = sc_ptr + 1;
        sc_cur = sc_ev_v[sc_ptr];
        sc_badv = 0;
        cmp_bits_(sc_cur[0:0], dut_ce, 1, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[0] = 1'b1; if (sc_nerr[0] == 0) sc_fcyc[0] = cyc; sc_nerr[0] = sc_nerr[0] + 1; end
        if (sc_badv != 0 && !sc_first) begin sc_first = 1; show_first; end
        checks = checks + 1;
    end endtask
    task summary; integer sh; begin
        sh = 0;
        if (sc_nerr[0] != 0) begin if (sh < 5) $display("FAIL: output ce: %0d mismatching sample points, first at cycle %0d", sc_nerr[0], sc_fcyc[0]); sh = sh + 1; end
        if (sh > 5) $display("FAIL: (%0d more signals fail)", sh - 5);
        sh = 0; $write("  pass: outputs that match at every sample point:");
        if (sc_nerr[0] == 0) begin if (sh < 12) $write(" ce"); sh = sh + 1; end
        if (sh == 0) $write(" none"); if (sh > 12) $write(" (+%0d more)", sh - 12);
        $display("");
    end endtask
    initial begin
        errs = 0; checks = 0; known = 0; cyc = 0;
        sc_ptr = 0; sc_sptr = 0; sc_first = 0;
        for (sc_k = 0; sc_k < 1; sc_k = sc_k + 1) begin sc_nerr[sc_k] = 0; sc_fcyc[sc_k] = -1; end
        seed = 9001;
        cycles = 8000;
        seed0 = seed;
        reset = 1'b0;
        #(0.5);
        while (cyc < cycles) begin check; #(1.0); end
        if (checks != SC_NCHECKS) begin errs = errs + 1;
            $display("FAIL: testbench ran %0d checks, the vectors hold %0d", checks, SC_NCHECKS); end
        if (errs == 0) begin
            $display("selfcheck: seed 9001, %0d cycles, %0d sample points, %0d known output bits compared", cyc, checks, known);
            $display("PASS");
        end else begin summary; $display("FAIL: %0d mismatches", errs); end
        $finish;
    end
endmodule
